CREATE TEMP TABLE _bc_match AS
WITH x_name AS (  -- nombres cuyas filas del Excel comparten un único código (y todas lo tienen)
       SELECT name, min(barcode) AS barcode, count(*) AS n FROM _bc
       GROUP BY name HAVING count(DISTINCT barcode) = 1 AND count(barcode) = count(*)),
     p_name AS (SELECT name, count(*) AS n FROM products GROUP BY name),
     x_np AS (
       SELECT name, price, min(barcode) AS barcode, count(*) AS n FROM _bc
       GROUP BY name, price HAVING count(DISTINCT barcode) = 1 AND count(barcode) = count(*)),
     p_np AS (SELECT name, price, count(*) AS n FROM products GROUP BY name, price),
     by_name AS (
       SELECT p.id, x.barcode, 'nombre'::text AS how
       FROM products p
       JOIN x_name x ON x.name = p.name
       JOIN p_name c ON c.name = p.name
       WHERE p.barcode IS NULL AND c.n <= x.n)
SELECT * FROM by_name
UNION ALL
SELECT p.id, x.barcode, 'nombre+precio'
FROM products p
JOIN x_np x ON x.name = p.name AND x.price = p.price
JOIN p_np c ON c.name = p.name AND c.price = p.price
WHERE p.barcode IS NULL AND c.n <= x.n
  AND p.id NOT IN (SELECT id FROM by_name);

DO $report$
DECLARE
  total INT := (SELECT count(*) FROM products);
  with_code INT := (SELECT count(*) FROM products WHERE barcode IS NOT NULL);
  by_name INT := (SELECT count(*) FROM _bc_match WHERE how = 'nombre');
  by_pair INT := (SELECT count(*) FROM _bc_match WHERE how = 'nombre+precio');
  not_in_excel INT := (SELECT count(*) FROM products p WHERE p.barcode IS NULL AND NOT EXISTS (SELECT 1 FROM _bc b WHERE b.name = p.name));
BEGIN
  RAISE NOTICE 'Productos en la base de datos: %. Ya tenían código: %.', total, with_code;
  RAISE NOTICE 'Se rellenan por nombre: %, por nombre+precio: %.', by_name, by_pair;
  RAISE NOTICE 'Sin código y sin aparecer en el Excel (p. ej. productos nuevos): %.', not_in_excel;
  RAISE NOTICE 'Sin código por ambigüedad (nombre repetido): %.',
    (SELECT count(*) FROM products p WHERE p.barcode IS NULL AND NOT EXISTS (SELECT 1 FROM _bc_match m WHERE m.id = p.id)
       AND EXISTS (SELECT 1 FROM _bc b WHERE b.name = p.name AND b.barcode IS NOT NULL)) ;
END
$report$;

UPDATE products p SET barcode = m.barcode FROM _bc_match m WHERE p.id = m.id AND p.barcode IS NULL;

DROP TABLE _bc, _bc_match;
